import{_ as a,o,c as e,ag as r}from"./chunks/framework.CvZZEx4j.js";const p=JSON.parse('{"title":"语音合成 (TTS)","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/tts.md","filePath":"advanced/tts.md","lastUpdated":null}'),l={name:"advanced/tts.md"};function i(s,t,n,d,h,c){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="语音合成-tts" tabindex="-1">语音合成 (TTS) <a class="header-anchor" href="#语音合成-tts" aria-label="Permalink to &quot;语音合成 (TTS)&quot;">​</a></h1><h2 id="支持的引擎" tabindex="-1">支持的引擎 <a class="header-anchor" href="#支持的引擎" aria-label="Permalink to &quot;支持的引擎&quot;">​</a></h2><table tabindex="0"><thead><tr><th>引擎</th><th>说明</th><th>适合场景</th></tr></thead><tbody><tr><td><strong>小白盒 (LittleWhiteBox)</strong></td><td>默认引擎，开箱即用</td><td>快速体验</td></tr><tr><td><strong>GPT-SoVITS</strong></td><td>本地语音合成引擎，音质更高</td><td>追求高品质</td></tr></tbody></table><h2 id="基本设置" tabindex="-1">基本设置 <a class="header-anchor" href="#基本设置" aria-label="Permalink to &quot;基本设置&quot;">​</a></h2><p>在 <strong>设置面板</strong> → <strong>音频设置</strong> 中：</p><ol><li><strong>启用/禁用 TTS</strong>：总开关</li><li><strong>自动播放</strong>：是否在每段对话后自动播放语音</li><li><strong>角色-音色绑定</strong>：为每个角色指定专属音色</li></ol><h2 id="角色音色绑定" tabindex="-1">角色音色绑定 <a class="header-anchor" href="#角色音色绑定" aria-label="Permalink to &quot;角色音色绑定&quot;">​</a></h2><ol><li>在音频设置中找到「角色音色」</li><li>选择角色名</li><li>从音色列表中选择合适的音色</li><li>保存后，该角色的所有对话都会使用绑定的音色</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>绑定信息会自动反映到 COT 世界书中，AI 也会在输出中遵守音色分配。</p></div><h2 id="gpt-sovits-配置" tabindex="-1">GPT-SoVITS 配置 <a class="header-anchor" href="#gpt-sovits-配置" aria-label="Permalink to &quot;GPT-SoVITS 配置&quot;">​</a></h2><p>如果你本地运行了 GPT-SoVITS 语音服务：</p><ol><li><strong>API 地址</strong>：填写服务地址（默认 <code>http://127.0.0.1:9880</code>）</li><li><strong>代理设置</strong>：如需跨域访问，启用 CORS 代理</li><li><strong>模型管理</strong>：添加/切换参考音频模型</li><li><strong>语速调节</strong>：控制语音播放速度</li><li><strong>流式模式</strong>：启用流式传输以减少延迟</li><li><strong>语言设置</strong>：选择文本语言（自动/中/英/日等）</li></ol><h2 id="与-live2d-口型联动" tabindex="-1">与 Live2D 口型联动 <a class="header-anchor" href="#与-live2d-口型联动" aria-label="Permalink to &quot;与 Live2D 口型联动&quot;">​</a></h2><p>当同时启用 TTS 和 Live2D 时，角色说话的语音会驱动 Live2D 模型的口型同步动画。详见 <a href="/galgame/advanced/live2d.html#口型同步">Live2D 章节</a>。</p>',14)])])}const T=a(l,[["render",i]]);export{p as __pageData,T as default};
